  const start = view.coordsAtPos(from);
  const end = view.coordsAtPos(to);
  if (!start || !end) return false;
  const x = event.clientX;
  const y = event.clientY;
  return x >= start.left && x <= end.right && y >= start.top && y <= end.bottom;
