function reindexAfterRemove(
  record: Record<number, string>,
  removedIndex: number,
): Record<number, string> {
  const next: Record<number, string> = {};
  for (const [key, value] of Object.entries(record)) {
    const i = Number(key);
    if (i < removedIndex) {
      next[i] = value;
    } else if (i > removedIndex) {
      next[i - 1] = value;
    }
  }
  return next;
}

